<script>
  (function () {
    const DURATION_SEC = 34;
    const DURATION_MS = DURATION_SEC * 1000;
    const startTime = performance.now();

    const labelsHistory = [
      { text: "Buyer company", t: 0 },
      { text: "Gemini agent", t: 0 },
      { text: "Spend policy", t: 0 },
      { text: "Basis Theory vault", t: 0 },
      { text: "Merchant", t: 0 },
      { text: "Base Sepolia chain", t: 0 }
    ];

    const elementsHistory = [
      { name: "buyer", visibleFrom: 0, visibleTo: DURATION_MS },
      { name: "agent", visibleFrom: 0, visibleTo: DURATION_MS },
      { name: "spend", visibleFrom: 0, visibleTo: DURATION_MS },
      { name: "vault", visibleFrom: 0, visibleTo: DURATION_MS },
      { name: "merchant", visibleFrom: 0, visibleTo: DURATION_MS },
      { name: "chain", visibleFrom: 0, visibleTo: DURATION_MS }
    ];

    const marks = [];

    window.__theater = {
      duration: DURATION_SEC,
      marks: marks,
      done: false,
      snapshot: function () {
        return {
          labels: labelsHistory.map(function (entry) {
            const copy = { text: entry.text, t: entry.t };
            if (entry.orderId) copy.orderId = entry.orderId;
            return copy;
          }),
          elements: elementsHistory.map(function (el) {
            const copy = {
              name: el.name,
              visibleFrom: el.visibleFrom,
              visibleTo: el.visibleTo
            };
            if (el.orderId) copy.orderId = el.orderId;
            return copy;
          })
        };
      }
    };

    window.__theaterInternal = {
      startTime: startTime,
      durationMs: DURATION_MS,
      labelsHistory: labelsHistory,
      elementsHistory: elementsHistory,
      recordLabel: function (text, tMs, orderId) {
        const entry = { text: text, t: Math.round(tMs) };
        if (orderId) entry.orderId = orderId;
        labelsHistory.push(entry);
      },
      recordElementStart: function (name, tMs, orderId) {
        const existing = elementsHistory.find(function (e) { return e.name === name; });
        if (existing) return existing;
        const entry = {
          name: name,
          visibleFrom: Math.round(tMs),
          visibleTo: DURATION_MS
        };
        if (orderId) entry.orderId = orderId;
        elementsHistory.push(entry);
        return entry;
      },
      recordElementEnd: function (name, tMs) {
        const existing = elementsHistory.find(function (e) { return e.name === name; });
        if (existing && existing.visibleTo === DURATION_MS) {
          existing.visibleTo = Math.round(tMs);
        }
      },
      recordMark: function (tMs, kind, orderId, element) {
        marks.push({
          t: Math.round(tMs),
          kind: kind,
          orderId: orderId,
          element: element
        });
      }
    };
  })();
</script>

