<script type="module">
  import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

  const eventsData = JSON.parse(document.getElementById('events').textContent);
  const evRefused = eventsData[0];
  const evSettled = eventsData[1];
  const internal = window.__theaterInternal;

  const container = document.getElementById('stage-container');
  const overlayLayer = document.getElementById('overlay-layer');
  const captionBar = document.getElementById('caption-bar');
  const initialSvg = document.getElementById('initial-stage-svg');

  // --- Scene, Camera, Renderer ---
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0xf3ead7);

  const camera = new THREE.PerspectiveCamera(
    33,
    window.innerWidth / window.innerHeight,
    0.1,
    100
  );
  camera.position.set(0, 6.8, 30.5);
  camera.lookAt(0, 0.7, 0);

  const renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  container.insertBefore(renderer.domElement, overlayLayer);

  // --- Lighting ---
  const ambientLight = new THREE.AmbientLight(0xfff8eb, 1.35);
  scene.add(ambientLight);

  const dirLight = new THREE.DirectionalLight(0xfff4df, 1.5);
